df = {"kargo": 4, "urun": 6, "hizli": 2}
N = 6
for t in ["kargo", "urun", "hizli"]:
    idf = math.log10(N / df[t])
    print(t, round(idf, 4), round(tf[t] * idf, 4))
norm = math.sqrt(sum((tf[t] * math.log10(N / df[t])) ** 2 for t in tf))
